import { Suspense } from "react";
import { notFound } from "next/navigation";
import { connection } from "next/server";
import { getTrack } from "@/lib/db/tracks";
import { listApplications } from "@/lib/db/applications";
import { NewApplicationForm } from "./new-application-form";

// Typed by hand: PageProps<> is generated by `next build`, so a fresh-checkout `tsc` (CI order) would fail.
// Params and DB are request-time under cacheComponents, so everything lives inside the Suspense boundary.
async function TrackView({ params }: { params: Promise<{ id: string }> }) {
  await connection();
  const { id: raw } = await params;
  const id = /^\d+$/.test(raw) ? Number(raw) : NaN;
  const track = Number.isSafeInteger(id) ? await getTrack(id) : null;
  if (!track) notFound();
  const apps = await listApplications(track.id);
  return (
    <>
      <h1 className="mb-4 text-2xl font-semibold">{track.name}</h1>
      <NewApplicationForm trackId={track.id} />
      {apps.length === 0 ? (
        <p>No applications yet.</p>
      ) : (
        <ul className="list-disc pl-6">
          {apps.map((a) => (
            <li key={a.id}>{a.title}</li>
          ))}
        </ul>
      )}
    </>
  );
}

export default function TrackPage(props: { params: Promise<{ id: string }> }) {
  return (
    <Suspense fallback={<p>Loading…</p>}>
      <TrackView params={props.params} />
    </Suspense>
  );
}
